CREATE COLUMN TABLE "TEST_AP"."OWGT" ("UnitCode" SMALLINT CS_INT NOT NULL , "UnitDisply" NVARCHAR(2) NOT NULL , "UnitName" NVARCHAR(20) NOT NULL , "WightInMG" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("UnitCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWGT_DISPLAY" ON "TEST_AP"."OWGT" ( "UnitDisply" ASC );
CREATE UNIQUE INDEX "OWGT_UNIT_NAME" ON "TEST_AP"."OWGT" ( "UnitName" ASC )